(()=>{const A='#e1c08e',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`.fx-progress{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fx-progress i{display:block;height:100%;width:0;background:${A};box-shadow:0 0 14px ${A}}.fx-projector-light{position:fixed;left:50%;top:45%;width:2px;height:2px;border-radius:50%;background:#fff;box-shadow:0 0 120px 55px ${A}18;pointer-events:none;z-index:0;animation:lamp 3s ease-in-out infinite}.fx-reveal{opacity:0;transform:translateY(35px) scale(.985);transition:opacity 1s ease,transform 1s cubic-bezier(.2,.8,.2,1)}.fx-visible{opacity:1!important;transform:none!important}.projector.show .beam{animation:beam 1.2s ease both}.projected.on{animation:project .9s ease both}.film-count{animation:count 1s ease}.fx-dust,.fx-particle{position:fixed;border-radius:50%;pointer-events:none}.fx-dust{width:3px;height:3px;background:#fff;opacity:0;animation:dust 5s linear infinite}.fx-particle{width:2px;height:2px;background:${A};box-shadow:0 0 9px ${A};opacity:0;animation:particle 8s ease-in-out infinite}@keyframes lamp{50%{opacity:.55;transform:scale(1.25)}}@keyframes beam{from{opacity:0;transform:scaleX(.3)}to{opacity:1;transform:scaleX(1)}}@keyframes project{0%{opacity:0;filter:blur(8px);transform:scale(.96)}60%{opacity:1;filter:blur(0);transform:scale(1.02)}100%{transform:none}}@keyframes count{50%{transform:scale(1.15);opacity:.6}}@keyframes dust{0%{transform:translateY(20vh);opacity:0}20%{opacity:.4}100%{transform:translateY(-20vh) translateX(40px);opacity:0}}@keyframes particle{0%{transform:translate3d(0,18vh,0) scale(.3);opacity:0}20%{opacity:.35}55%{transform:translate3d(-20px,-32vh,0) scale(1)}100%{transform:translate3d(20px,-80vh,0) scale(.15);opacity:0}}`;b.appendChild(s);const p=document.createElement('div');p.className='fx-progress';p.innerHTML='<i></i>';b.appendChild(p);const l=document.createElement('div');l.className='fx-projector-light';b.appendChild(l);if(!reduce){for(let i=0;i<18;i++){const d=document.createElement('span');d.className='fx-dust';d.style.left=Math.random()*100+'%';d.style.top=Math.random()*100+'%';d.style.animationDelay=-Math.random()*5+'s';b.appendChild(d)}for(let i=0;i<28;i++){const x=document.createElement('i');x.className='fx-particle';x.style.left=Math.random()*100+'%';x.style.bottom=-5-Math.random()*20+'px';x.style.animationDelay=-Math.random()*8+'s';x.style.animationDuration=6+Math.random()*5+'s';b.appendChild(x)}}document.querySelectorAll('section').forEach(s=>s.classList.add('fx-reveal'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('fx-visible');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fx-reveal').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;p.firstElementChild.style.width=(max?scrollY/max*100:0)+'%'})})();